/**
 * Display formatting for the system-prompt viewer.
 *
 * The `<available_skills>` block is machine-generated by pi
 * (dist/core/skills.js): name/description/location are XML-escaped, and a
 * skill whose SKILL.md description is a multi-line YAML scalar keeps its
 * literal newlines — which lands text and the closing tag at column 0 and
 * visually breaks the nesting. For display, the block is re-rendered with
 * canonical two-space indentation, entity-decoded text and collapsed in-tag
 * whitespace. Everything outside the block passes through untouched, and any
 * parse surprise falls back to the raw block: the viewer re-lays-out existing
 * content, it never invents any.
 */

interface XmlElement {
  tag: string
  children: Array<XmlElement | string>
}

const TAG_RE = /<(\/?)([a-zA-Z][\w-]*)>/g
const SKILLS_BLOCK_RE = /<available_skills>[\s\S]*?<\/available_skills>/
/** Elements whose single-line rendering would exceed this are split so their
 * text sits on its own indented line. */
const INLINE_LIMIT = 110

/** Reverse pi's `escapeXml`: named entities first, `&amp;` last, so a literal
 * `&amp;lt;` in the source decodes to `&lt;` rather than `<`. */
function unescapeXml(text: string): string {
  return text
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
}

/** Tiny XML-fragment parser; returns null on any imbalance so the caller can
 * fall back to the untouched source. */
function parseFragment(source: string): XmlElement | null {
  const root: XmlElement = { tag: '', children: [] }
  const stack: XmlElement[] = [root]
  let last = 0
  for (const match of source.matchAll(TAG_RE)) {
    const text = source.slice(last, match.index)
    if (text.trim()) stack[stack.length - 1].children.push(text)
    last = match.index + match[0].length
    if (match[1]) {
      if (stack.length < 2 || stack[stack.length - 1].tag !== match[2]) return null
      stack.pop()
    } else {
      const element: XmlElement = { tag: match[2], children: [] }
      stack[stack.length - 1].children.push(element)
      stack.push(element)
    }
  }
  const tail = source.slice(last)
  if (tail.trim()) stack[stack.length - 1].children.push(tail)
  return stack.length === 1 ? root : null
}

/** Literal newlines inside a field (multi-line YAML descriptions) become
 * single spaces; entities are decoded. */
function collapseText(parts: string[]): string {
  return unescapeXml(parts.join(' ').replace(/\s+/g, ' ').trim())
}

function renderElement(element: XmlElement, depth: number, lines: string[]): void {
  const indent = '  '.repeat(depth)
  const hasElementChild = element.children.some((child) => typeof child !== 'string')
  if (!hasElementChild) {
    const text = collapseText(element.children as string[])
    const oneLine = `${indent}<${element.tag}>${text}</${element.tag}>`
    if (oneLine.length <= INLINE_LIMIT) {
      lines.push(oneLine)
    } else {
      lines.push(`${indent}<${element.tag}>`)
      if (text) lines.push(`${'  '.repeat(depth + 1)}${text}`)
      lines.push(`${indent}</${element.tag}>`)
    }
    return
  }
  lines.push(`${indent}<${element.tag}>`)
  let pending: string[] = []
  const flush = () => {
    const text = collapseText(pending)
    if (text) lines.push(`${'  '.repeat(depth + 1)}${text}`)
    pending = []
  }
  for (const child of element.children) {
    if (typeof child === 'string') pending.push(child)
    else {
      flush()
      renderElement(child, depth + 1, lines)
    }
  }
  flush()
  lines.push(`${indent}</${element.tag}>`)
}

/**
 * Re-indent the machine-generated `<available_skills>` block for display.
 * Returns the prompt unchanged when the block is absent or fails to parse.
 */
export function formatSystemPromptForDisplay(prompt: string): string {
  const match = SKILLS_BLOCK_RE.exec(prompt)
  if (!match) return prompt
  try {
    const parsed = parseFragment(match[0])
    if (!parsed) return prompt
    const lines: string[] = []
    for (const child of parsed.children) {
      if (typeof child !== 'string') renderElement(child, 0, lines)
    }
    if (lines.length === 0) return prompt
    return prompt.slice(0, match.index) + lines.join('\n') + prompt.slice(match.index + match[0].length)
  } catch {
    return prompt
  }
}
